export var CommentType;
(function (CommentType) {
    CommentType["PAGE"] = "page";
    CommentType["PRODUCT"] = "product";
    CommentType["BLOG"] = "blog";
})(CommentType || (CommentType = {}));
export function isFeatureEnabled(feature) {
    return !!salla.config.get('store.features')?.includes(feature);
}
export function buildCommentSortOptions({ mostHelpfulLabel, verifiedPurchasesLabel, allowLikes, allowVerifiedPurchasesFilter, }) {
    const options = [
        { value: 'latest', label: salla.lang.get('pages.testimonials.sort_by_date_desc'), selected: true },
        { value: 'oldest', label: salla.lang.get('pages.testimonials.sort_by_date_asc') },
        { value: 'most_helpful', label: mostHelpfulLabel, show: allowLikes },
        { value: 'verified_purchases', label: verifiedPurchasesLabel, show: allowVerifiedPurchasesFilter },
    ];
    return options.filter(option => option.show !== false);
}
